// Aggregate AI Results - consolida resultados del test con usuario simulado por IA
const testCase = $('Pre-Test Log').first().json;

// Obtener resultados de turnos
let turnResults = [];
try {
  const existing = $execution.customData.get('aiTurnResults');
  if (existing) turnResults = JSON.parse(existing);
} catch(e) {}

// Obtener resultados de verificación DB
const dbResults = $input.all();
const verification = testCase.verification;

// Evaluar verificación de DB
let dbPassed = true;
let dbDetails = [];

if (verification && verification.queries) {
  verification.queries.forEach((query, idx) => {
    const result = dbResults[idx];
    let actualValue = 0;

    if (result && result.json) {
      actualValue = result.json.cnt || result.json.count || Object.values(result.json)[0] || 0;
    }

    const queryPassed = Number(actualValue) >= query.expected;
    dbPassed = dbPassed && queryPassed;

    dbDetails.push({
      query: query.sql.substring(0, 50) + '...',
      expected: query.expected,
      actual: actualValue,
      passed: queryPassed
    });

    const emoji = queryPassed ? '✅' : '❌';
    console.log(`   ${emoji} DB Check ${idx + 1}: expected ${query.expected}, got ${actualValue}`);
  });
}

// Verificar si el KYC se completó (el último turno debe tener isComplete=true)
const lastTurn = turnResults[turnResults.length - 1];
const kycCompleted = lastTurn && lastTurn.isComplete;
const totalTurns = turnResults.length;

// El test pasa si: KYC completó Y todas las verificaciones de DB pasaron
const overallPassed = dbPassed; // DB verification es la fuente de verdad

console.log(`\n📊 Resultado AI Multi-Turn:`);
console.log(`   Turnos ejecutados: ${totalTurns}`);
console.log(`   KYC Completado: ${kycCompleted ? 'SÍ' : 'NO'}`);
console.log(`   DB Verification: ${dbPassed ? 'PASSED' : 'FAILED'}`);
console.log(`   Overall: ${overallPassed ? '✅ PASSED' : '❌ FAILED'}`);

// Construir resultado final
const result = {
  testId: testCase.id,
  testName: testCase.name,
  category: testCase.category,
  priority: testCase.priority,
  passed: overallPassed,
  output: `AI Turns: ${totalTurns}. KYC: ${kycCompleted ? 'Complete' : 'Incomplete'}. DB: ${dbPassed ? 'OK' : 'FAIL'}`,
  expectedRule: testCase.metrics.rule,
  ruleDescription: testCase.metrics.description,
  error: overallPassed ? null : `KYC ${kycCompleted ? 'completed' : 'not completed'}. DB ${dbPassed ? 'passed' : 'failed'}`,
  executedAt: new Date().toISOString(),
  details: {
    totalTurns,
    kycCompleted,
    turns: turnResults,
    dbVerification: dbDetails
  }
};

// Guardar en customData para el reporte final
let allResults = [];
try {
  const existing = $execution.customData.get('testResults');
  if (existing) allResults = JSON.parse(existing);
} catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));

return [{ json: result }];

// Process AI Response - extrae la respuesta del usuario simulado
const apiResponse = $input.first().json;

let userMessage = '';
try {
  userMessage = apiResponse.choices[0].message.content.trim();
} catch(e) {
  console.log('Error parsing OpenAI response:', e.message);
  userMessage = 'Sí';
}

// Obtener el número de turno actual
const turnCount = parseInt($execution.customData.get('aiTurnCount') || '0');

// Guardar en historial
let history = [];
try {
  const existing = $execution.customData.get('conversationHistory');
  if (existing) history = JSON.parse(existing);
} catch(e) {}
history.push({ role: 'user', content: userMessage });
$execution.customData.set('conversationHistory', JSON.stringify(history));

console.log(`   🧑 AI User Response: "${userMessage.substring(0, 60)}..."`);

return [{ 
  json: {
    currentMessage: userMessage,
    turnNumber: turnCount + 1,
    isFirstTurn: false
  }
}];

