// Check Completion - verifica si el KYC terminó o si hay que continuar
const testCase = $('Pre-Test Log').first().json;
const workflowResult = $input.first().json;

// Extraer el output del workflow
let output = '';
try {
  if (workflowResult.output) {
    output = workflowResult.output;
  } else if (workflowResult.text) {
    output = workflowResult.text;
  } else if (typeof workflowResult === 'string') {
    output = workflowResult;
  } else {
    const findOutput = (obj) => {
      if (!obj || typeof obj !== 'object') return '';
      if (obj.output) return obj.output;
      if (obj.text) return obj.text;
      for (const key of Object.keys(obj)) {
        const found = findOutput(obj[key]);
        if (found) return found;
      }
      return '';
    };
    output = findOutput(workflowResult);
  }
} catch (e) {
  output = '';
}

// Verificar indicadores de finalización
const outputLower = output.toLowerCase();
const isComplete = testCase.config.completionIndicators.some(indicator =>
  outputLower.includes(indicator.toLowerCase())
);

// Obtener contador de turnos
let turnCount = parseInt($execution.customData.get('aiTurnCount') || '0');
turnCount++;
$execution.customData.set('aiTurnCount', String(turnCount));

const maxTurnsReached = turnCount >= testCase.config.maxTurns;

// Guardar resultado del turno
let turnResults = [];
try {
  const existing = $execution.customData.get('aiTurnResults');
  if (existing) turnResults = JSON.parse(existing);
} catch(e) {}

turnResults.push({
  turn: turnCount,
  kycResponse: output.substring(0, 500),
  isComplete,
  timestamp: new Date().toISOString()
});
$execution.customData.set('aiTurnResults', JSON.stringify(turnResults));

// Guardar historial de conversación para el simulador
let history = [];
try {
  const existing = $execution.customData.get('conversationHistory');
  if (existing) history = JSON.parse(existing);
} catch(e) {}
history.push({ role: 'assistant', content: output });
$execution.customData.set('conversationHistory', JSON.stringify(history));

const emoji = isComplete ? '🎉' : (maxTurnsReached ? '⚠️' : '🔄');
console.log(`   ${emoji} Turn ${turnCount}: ${isComplete ? 'KYC COMPLETE!' : (maxTurnsReached ? 'MAX TURNS' : 'Continuing...')}`);

return [{ 
  json: {
    output,
    turnCount,
    isComplete,
    maxTurnsReached,
    shouldContinue: !isComplete && !maxTurnsReached
  }
}];

// Build AI Turn Input - construye el mensaje WhatsApp para el turno actual
const testCase = $('Pre-Test Log').first().json;
const turnData = $input.first().json;
const turnNumber = turnData.turnNumber || 1;
const message = turnData.currentMessage;

// Usar phone del test case o default a 570000000009
const phone = testCase.phone || "570000000009";

console.log(`   📤 AI Turn ${turnNumber}: "${message.substring(0, 60)}..."`);

return [{
  json: {
    messaging_product: "whatsapp",
    metadata: {
      display_phone_number: "573213413664",
      phone_number_id: "914510145083991"
    },
    contacts: [{
      profile: { name: testCase.simulatedUser?.nombre || "Test KYC User" },
      wa_id: phone
    }],
    messages: [{
      from: phone,
      id: `wamid.E2E-${testCase.id}-TURN${turnNumber}`,
      timestamp: String(Math.floor(Date.now() / 1000)),
      text: { body: message },
      type: "text"
    }],
    field: "messages"
  }
}];

// Initialize AI Loop - prepara el loop dinámico para el test con IA
const testCase = $('Pre-Test Log').first().json;

// Inicializar contadores
$execution.customData.set('aiTurnCount', '0');
$execution.customData.set('aiTurnResults', '[]');
$execution.customData.set('conversationHistory', '[]');

console.log(`\n🤖 Iniciando test AI-Simulated User`);
console.log(`   Max turns: ${testCase.config.maxTurns}`);
console.log(`   Usuario simulado: ${testCase.simulatedUser.nombre}`);

// Retornar el primer mensaje
return [{ 
  json: {
    currentMessage: testCase.config.firstMessage,
    turnNumber: 1,
    isFirstTurn: true
  }
}];

// Aggregate Multi-Turn Results - consolida resultados de todos los turnos y verificación DB
const testCase = $('Pre-Test Log').first().json;

// Obtener resultados de turnos
let turnResults = [];
try {
  const existing = $execution.customData.get('turnResults');
  if (existing) turnResults = JSON.parse(existing);
} catch(e) {}

// Obtener resultados de verificación DB
const dbResults = $input.all();
const verification = testCase.verification;

// Evaluar verificación de DB
let dbPassed = true;
let dbDetails = [];

if (verification && verification.queries) {
  verification.queries.forEach((query, idx) => {
    const result = dbResults[idx];
    let actualValue = 0;

    if (result && result.json) {
      // El resultado puede venir como cnt o como el primer valor del objeto
      actualValue = result.json.cnt || result.json.count || Object.values(result.json)[0] || 0;
    }

    const queryPassed = Number(actualValue) >= query.expected;
    dbPassed = dbPassed && queryPassed;

    dbDetails.push({
      query: query.sql.substring(0, 50) + '...',
      expected: query.expected,
      actual: actualValue,
      passed: queryPassed
    });

    const emoji = queryPassed ? '✅' : '❌';
    console.log(`   ${emoji} DB Check ${idx + 1}: expected ${query.expected}, got ${actualValue}`);
  });
}

// Calcular resultado final
const allTurnsPassed = turnResults.every(t => t.passed);
const overallPassed = allTurnsPassed && dbPassed;

const passedTurns = turnResults.filter(t => t.passed).length;
const totalTurns = turnResults.length;

console.log(`\n📊 Resultado Multi-Turn:`);
console.log(`   Turnos: ${passedTurns}/${totalTurns}`);
console.log(`   DB Verification: ${dbPassed ? 'PASSED' : 'FAILED'}`);
console.log(`   Overall: ${overallPassed ? '✅ PASSED' : '❌ FAILED'}`);

// Construir resultado final en el mismo formato que Evaluate Result
const result = {
  testId: testCase.id,
  testName: testCase.name,
  category: testCase.category,
  priority: testCase.priority,
  passed: overallPassed,
  output: `Turns: ${passedTurns}/${totalTurns} passed. DB: ${dbPassed ? 'OK' : 'FAIL'}`,
  expectedRule: testCase.metrics.rule,
  ruleDescription: testCase.metrics.description,
  error: overallPassed ? null : `Failed turns: ${turnResults.filter(t => !t.passed).map(t => t.turn).join(', ')}`,
  executedAt: new Date().toISOString(),
  details: {
    turns: turnResults,
    dbVerification: dbDetails
  }
};

// Guardar en customData para el reporte final
let allResults = [];
try {
  const existing = $execution.customData.get('testResults');
  if (existing) allResults = JSON.parse(existing);
} catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));

return [{ json: result }];

// Prepare Turns - convierte el array de turns en items para el loop
const testCase = $('Pre-Test Log').first().json;

// Limpiar resultados previos de turnos
$execution.customData.set('turnResults', '[]');

console.log(`\n🔄 Iniciando test multi-turno: ${testCase.turns.length} turnos`);

// Retornar cada turno como un item separado
return testCase.turns.map((turn, index) => ({ 
  json: { 
    turnIndex: index,
    ...turn 
  } 
}));

// Evaluate Turn Result - evalúa si la respuesta del turno es correcta
// Obtener el turno actual desde Build Turn Input (viene en el contexto del loop)
const testCase = $('Pre-Test Log').first().json;
const buildTurnInput = $('Build Turn Input').first().json;
const workflowResult = $input.first().json;

// Encontrar el turno actual basado en el mensaje enviado
const currentMessage = buildTurnInput.messages[0].text.body;
const turn = testCase.turns.find(t => t.message === currentMessage);

if (!turn) {
  throw new Error(`Turn not found for message: ${currentMessage}`);
}

// Extraer el output
let output = '';
try {
  if (workflowResult.output) {
    output = workflowResult.output;
  } else if (workflowResult.text) {
    output = workflowResult.text;
  } else if (typeof workflowResult === 'string') {
    output = workflowResult;
  } else {
    const findOutput = (obj) => {
      if (!obj || typeof obj !== 'object') return '';
      if (obj.output) return obj.output;
      if (obj.text) return obj.text;
      for (const key of Object.keys(obj)) {
        const found = findOutput(obj[key]);
        if (found) return found;
      }
      return '';
    };
    output = findOutput(workflowResult);
  }
} catch (e) {
  output = '';
}

// Evaluar si contiene alguna de las palabras esperadas
const outputLower = output.toLowerCase();
const passed = turn.expectContains.some(keyword => 
  outputLower.includes(keyword.toLowerCase())
);

const emoji = passed ? '✅' : '❌';
console.log(`   ${emoji} Turn ${turn.turn}: ${passed ? 'PASSED' : 'FAILED'}`);
if (!passed) {
  console.log(`      Expected one of: ${turn.expectContains.join(', ')}`);
  console.log(`      Got: ${output.substring(0, 100)}...`);
}

// Guardar resultado del turno
let turnResults = [];
try {
  const existing = $execution.customData.get('turnResults');
  if (existing) turnResults = JSON.parse(existing);
} catch(e) {}

turnResults.push({
  turn: turn.turn,
  message: turn.message,
  passed,
  output: output.substring(0, 300),
  expected: turn.expectContains
});
$execution.customData.set('turnResults', JSON.stringify(turnResults));

return [{ json: { turn: turn.turn, passed, output: output.substring(0, 300) } }];

// Build Turn Input - construye el mensaje WhatsApp para cada turno
// El turno actual viene del input (pasado por Prepare Turns -> Multi-Turn Loop)
const currentTurn = $input.first().json;

console.log(`   📤 Turn ${currentTurn.turn}: "${currentTurn.message.substring(0, 50)}..."`);

return [{ 
  json: {
    messaging_product: "whatsapp",
    metadata: { 
      display_phone_number: "573213413664", 
      phone_number_id: "914510145083991" 
    },
    contacts: [{ 
      profile: { name: "Test KYC User" }, 
      wa_id: "570000000009" 
    }],
    messages: [{
      from: "570000000009",
      id: `wamid.E2E-TC002-FULL-TURN${currentTurn.turn}`,
      timestamp: String(Math.floor(Date.now() / 1000)),
      text: { body: currentTurn.message },
      type: "text"
    }],
    field: "messages"
  }
}];

// 1. DATA EXTRACTION
// ------------------------------------------------
let results = [];
let source = 'None';

// Check if input exists and has the 'results' key (matches your specific input)
if (items && items.length > 0 && items[0].json && Array.isArray(items[0].json.results)) {
  results = items[0].json.results;
  source = 'items[0].json.results';
} 
// Fallback: If the input is the array itself
else if (items && items.length > 0 && Array.isArray(items[0].json)) {
  results = items[0].json;
  source = 'items[0].json (Direct)';
}

// Debug Log for the Console Tab
console.log(`\n🔍 DATA SOURCE: ${source}`);
console.log(`📊 RECORDS FOUND: ${results.length}`);

// 2. STATISTICS CALCULATION
// ------------------------------------------------
const total = results.length;
const passed = results.filter(r => r.passed);
const failed = results.filter(r => !r.passed);

// Calculate Pass Rate (Avoid division by zero)
const passRateRaw = total > 0 ? (passed.length / total) * 100 : 0;
const passRate = passRateRaw % 1 === 0 ? passRateRaw.toFixed(0) : passRateRaw.toFixed(1);

// Group by Category
const byCategory = results.reduce((acc, curr) => {
  const cat = curr.category || 'UNCATEGORIZED';
  if (!acc[cat]) acc[cat] = { total: 0, passed: 0, failed: 0 };

  acc[cat].total++;
  curr.passed ? acc[cat].passed++ : acc[cat].failed++;
  return acc;
}, {});

// Group by Priority
const byPriority = results.reduce((acc, curr) => {
  const prio = curr.priority || 'UNKNOWN';
  if (!acc[prio]) acc[prio] = { total: 0, passed: 0, failed: 0 };

  acc[prio].total++;
  curr.passed ? acc[prio].passed++ : acc[prio].failed++;
  return acc;
}, {});

// 3. GENERATE MARKDOWN REPORT (For Slack/Telegram/Email)
// ------------------------------------------------
let statusEmoji = failed.length === 0 ? '✅' : '❌';
if (total === 0) statusEmoji = '⚠️';

let mdReport = `*📊 Test Report - GymRatFlow*\n`;
mdReport += `──────────────────────\n`;
mdReport += `*Status:* ${statusEmoji} ${failed.length === 0 ? 'PASS' : 'FAIL'}\n`;
mdReport += `*Score:* ${passRate}% (${passed.length}/${total})\n`;
mdReport += `*Time:* ${new Date().toLocaleString('es-CO')}\n\n`; // Adjusted to your locale context

// Add Category Summary
mdReport += `*📂 Categorías:*\n`;
Object.keys(byCategory).forEach(cat => {
  const c = byCategory[cat];
  const icon = c.failed === 0 ? '✔' : '❗';
  mdReport += `${icon} ${cat}: ${c.passed}/${c.total}\n`;
});

// Add Detailed Failures if any
if (failed.length > 0) {
  mdReport += `\n*🚨 Fallos Detectados:*\n`;
  failed.forEach(f => {
    mdReport += `• *[${f.priority}] ${f.testName}*\n`;
    mdReport += `  _Exp:_ ${f.ruleDescription}\n`;
    // Clean output for message (truncate)
    const cleanOutput = (f.output || 'null').replace(/\n/g, ' ').substring(0, 80);
    mdReport += `  _Got:_ ${cleanOutput}...\n`;
  });
}

// 4. CONSOLE LOGGING (Visual Table for n8n UI)
// ------------------------------------------------
console.log('\n╔══════════════════════════════════════════════╗');
console.log(`║ STATUS: ${statusEmoji}  RATE: ${passRate}% (${passed.length}/${total})`.padEnd(47) + '║');
console.log('╠══════════════════════════════════════════════╣');
Object.keys(byCategory).forEach(cat => {
  const c = byCategory[cat];
  const bar = c.failed === 0 ? 'OK' : 'FAIL';
  console.log(`║ ${cat.padEnd(20)}: ${c.passed}/${c.total} ${bar.padStart(13)} ║`);
});
console.log('╚══════════════════════════════════════════════╝');

// 5. RETURN OUTPUT
// ------------------------------------------------
return [{
  json: {
    meta: {
      timestamp: new Date().toISOString(),
      totalTests: total,
      success: failed.length === 0
    },
    // This is the string you map to your Slack/Email node
    markdownReport: mdReport,
    // This object helps if you need to do conditional logic in Switch nodes next
    stats: {
      passed: passed.length,
      failed: failed.length,
      rate: parseFloat(passRate),
      byCategory,
      byPriority
    },
    // Only return detailed failure info to keep payload light
    failures: failed.map(r => ({
      testId: r.testId,
      name: r.testName,
      category: r.category,
      reason: r.ruleDescription,
      output: r.output
    }))
  }
}];

// Evaluar resultado del test
const testCase = $('Pre-Test Log').first().json;
const workflowResult = $input.first().json;

// Extraer el output del workflow
let output = '';
try {
  if (workflowResult.output) {
    output = workflowResult.output;
  } else if (workflowResult.text) {
    output = workflowResult.text;
  } else if (typeof workflowResult === 'string') {
    output = workflowResult;
  } else {
    const findOutput = (obj) => {
      if (!obj || typeof obj !== 'object') return '';
      if (obj.output) return obj.output;
      if (obj.text) return obj.text;
      for (const key of Object.keys(obj)) {
        const found = findOutput(obj[key]);
        if (found) return found;
      }
      return '';
    };
    output = findOutput(workflowResult);
  }
} catch (e) {
  output = '';
}

// Evaluar la métrica
let passed = false;
let error = null;

try {
  const rule = testCase.metrics.rule;
  passed = eval(rule);
} catch (e) {
  error = e.message;
  passed = false;
}

const result = {
  order: testCase.order,
  testId: testCase.id,
  testName: testCase.name,
  category: testCase.category,
  priority: testCase.priority,
  passed: passed,
  output: output ? output.substring(0, 500) : '(empty)',
  expectedRule: testCase.metrics.rule,
  ruleDescription: testCase.metrics.description,
  error: error,
  executedAt: new Date().toISOString()
};

// Guardar resultado en customData para agregarlo al final
let allResults = [];
try {
  const existing = $execution.customData.get('testResults');
  if (existing) allResults = JSON.parse(existing);
} catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));

console.log(`${passed ? '✅ PASSED' : '❌ FAILED'}: [${testCase.order}] ${testCase.id} - ${testCase.name}`);

return [{ json: result }];

// Extraer solo el input del test case para pasarlo al sub-workflow
const testCase = $('Pre-Test Log').first().json;
const whatsappInput = testCase.input[0];

// Retornar el objeto WhatsApp directamente
